"use client"

import * as React from "react"
import { motion, useReducedMotion } from "motion/react"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { useControllableState } from "@/hooks/use-controllable-state"
import {
  GridContainer,
  GridSection,
  GridSeparator,
} from "@/components/ui/grid-layout/grid-layout"
import { DEFAULT_LABELS, DEFAULT_TEAM_SIZES } from "./config"
import { Auth06DonePanel } from "./done-panel"
import { Auth06FormError } from "./form-parts"
import { Auth06Progress } from "./progress"
import {
  createAccountSchema,
  createIdentitySchema,
  createProfileSchema,
  fieldErrors,
} from "./schemas"
import {
  Auth06AccountForm,
  Auth06IdentityForm,
  Auth06ProfileForm,
} from "./step-forms"
import type {
  Auth06Draft,
  Auth06Errors,
  Auth06Props,
  Auth06Step,
  Auth06Values,
} from "./types"
import { useAsyncAction } from "./use-auth-form"

/** 多步注册向导：账号 → 资料 → 实名（可跳过），最后统一提交；真实注册由回调接入。 */
function Auth06({
  regions,
  onSubmit,
  onCheckEmail,
  onSuccess,
  onSignIn,
  identityStep = "optional",
  teamSizes = DEFAULT_TEAM_SIZES,
  agreementLinks,
  brand,
  labels: labelsProp,
  step: stepProp,
  defaultStep = "account",
  onStepChange,
  className,
  ...props
}: Auth06Props) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp }
  const [rawStep, setStep] = useControllableState<Auth06Step>({
    prop: stepProp,
    defaultProp: defaultStep,
    onChange: onStepChange,
  })
  // 关闭实名时，外部传入的 identity 按资料步处理
  const step =
    rawStep === "identity" && identityStep === "off" ? "profile" : rawStep
  const order: Auth06Step[] =
    identityStep === "off"
      ? ["account", "profile"]
      : ["account", "profile", "identity"]
  const [draft, setDraft] = React.useState<Auth06Draft>(() => ({
    email: "",
    password: "",
    agreed: false,
    name: "",
    phone: "",
    region: null,
    regionPath: [],
    teamSize: teamSizes[0]?.value ?? "",
    realName: "",
    idNumber: "",
  }))
  const [errors, setErrors] = React.useState<Auth06Errors>({})
  const [submitted, setSubmitted] = React.useState<Auth06Values | null>(null)
  const [submitKind, setSubmitKind] = React.useState<
    "identity" | "skip" | null
  >(null)
  // 真实姓名默认取第 2 步的姓名，用户改过之后不再覆盖
  const realNameEdited = React.useRef(false)
  const checking = useAsyncAction(labels.failed)
  const submitting = useAsyncAction(labels.failed)
  const pending = checking.pending || submitting.pending
  const titleRef = React.useRef<HTMLHeadingElement>(null)
  const previousStep = React.useRef(step)
  const focusTarget = React.useRef<string | null>(null)
  const reduced = useReducedMotion()
  const id = React.useId()
  const formErrorId = `${id}-form-error`

  React.useEffect(() => {
    if (previousStep.current !== step) titleRef.current?.focus()
    previousStep.current = step
  }, [step])
  // 校验失败后等错误渲染完，再把焦点交给第一个出错的字段
  React.useEffect(() => {
    if (!focusTarget.current) return
    document.getElementById(`${id}-${focusTarget.current}`)?.focus()
    focusTarget.current = null
  })

  function update(patch: Partial<Auth06Draft>) {
    if ("realName" in patch) realNameEdited.current = true
    setDraft((current) => ({ ...current, ...patch }))
    setErrors((current) => {
      const next = { ...current }
      for (const key of Object.keys(patch) as (keyof Auth06Draft)[])
        delete next[key]
      // 地区的值和路径一起变
      if ("region" in patch) delete next.regionPath
      return next
    })
    if ("email" in patch) checking.setError("")
    submitting.setError("")
  }

  function fail(next: Auth06Errors) {
    setErrors(next)
    focusTarget.current = Object.keys(next)[0] ?? null
  }

  function goTo(next: Auth06Step) {
    submitting.setError("")
    if (next === "identity" && !realNameEdited.current)
      setDraft((current) => ({ ...current, realName: current.name }))
    setStep(next)
  }

  async function submitAll(withIdentity: boolean) {
    if (pending) return
    if (withIdentity) {
      const result = createIdentitySchema(labels).safeParse(draft)
      if (!result.success) return fail(fieldErrors(result.error))
    }
    const values: Auth06Values = {
      email: draft.email.trim(),
      password: draft.password,
      name: draft.name.trim(),
      phone: draft.phone,
      region: { code: draft.region ?? "", path: draft.regionPath },
      teamSize: draft.teamSize,
      ...(withIdentity && {
        identity: {
          realName: draft.realName.trim(),
          idNumber: draft.idNumber,
        },
      }),
    }
    setSubmitKind(withIdentity ? "identity" : "skip")
    const ok = await submitting.run(() => onSubmit(values))
    setSubmitKind(null)
    if (ok) {
      setSubmitted(values)
      setStep("done")
    }
  }

  async function nextFromAccount() {
    if (pending) return
    const result = createAccountSchema(labels).safeParse(draft)
    if (!result.success) return fail(fieldErrors(result.error))
    const email = draft.email.trim()
    if (onCheckEmail && !(await checking.run(() => onCheckEmail(email)))) {
      focusTarget.current = "email"
      return
    }
    goTo("profile")
  }

  function nextFromProfile() {
    if (pending) return
    const result = createProfileSchema(labels).safeParse({
      ...draft,
      region: draft.region ?? "",
    })
    if (!result.success) return fail(fieldErrors(result.error))
    if (identityStep === "off") void submitAll(false)
    else goTo("identity")
  }

  const titles = {
    account: [labels.accountTitle, labels.accountDescription],
    profile: [labels.profileTitle, labels.profileDescription],
    identity: [labels.identityTitle, labels.identityDescription],
    done: [labels.doneTitle, labels.doneDescription],
  } satisfies Record<Auth06Step, string[]>
  const shortTitles = {
    account: labels.accountStep,
    profile: labels.profileStep,
    identity: labels.identityStep,
  }
  const skippedIdentity =
    step === "done" && identityStep !== "off" && !submitted?.identity
  const index = step === "done" ? order.length - 1 : order.indexOf(step)
  const shared = {
    id,
    labels,
    draft,
    errors,
    pending,
    update,
    describedBy: submitting.error ? formErrorId : undefined,
  }

  return (
    <div
      data-slot="auth-06"
      data-step={step}
      data-state={pending ? "pending" : step === "done" ? "success" : "idle"}
      className={cn(
        "w-full overflow-x-clip bg-background text-foreground",
        className,
      )}
      {...props}
    >
      <GridContainer className="max-w-4xl">
        <GridSection
          topLine
          className="grid divide-y divide-dashed divide-edge lg:grid-cols-[15rem_minmax(0,1fr)] lg:divide-x lg:divide-y-0"
        >
          <aside
            data-slot="auth-06-sidebar"
            className="flex flex-col gap-6 px-4 py-6 sm:px-6 lg:gap-10 lg:py-8"
          >
            <div>
              {brand && (
                <div className="mb-6 flex items-center gap-2 text-sm font-medium lg:mb-8">
                  {brand.logo}
                  {brand.name}
                </div>
              )}
              <h1 className="text-2xl font-semibold tracking-tight">
                {labels.title}
              </h1>
              <p className="mt-2 text-sm leading-6 text-muted-foreground">
                {labels.description}
              </p>
            </div>
            <Auth06Progress
              labels={labels}
              items={order.map((item) => ({
                title: shortTitles[item as keyof typeof shortTitles],
                description:
                  item !== "identity" || identityStep !== "optional"
                    ? undefined
                    : skippedIdentity
                      ? labels.skipped
                      : labels.optional,
                // 跳过实名后，结果页里这一步保持未完成
                skipped: item === "identity" && skippedIdentity,
              }))}
              index={index}
              done={step === "done"}
              locked={pending || step === "done"}
              onSelect={(target) => goTo(order[target] ?? "account")}
            />
          </aside>
          <div className="min-w-0 px-4 py-8 sm:px-6 lg:px-10 lg:py-10">
            <motion.div
              key={step}
              data-slot="auth-06-step"
              initial={false}
              animate={
                reduced
                  ? { opacity: 1, y: 0 }
                  : { opacity: [0.7, 1], y: [4, 0] }
              }
              transition={{ duration: reduced ? 0 : 0.18 }}
            >
              <h2
                ref={titleRef}
                tabIndex={-1}
                className="text-lg font-medium tracking-tight outline-none focus-visible:underline"
              >
                {titles[step][0]}
              </h2>
              <p className="mt-1.5 mb-6 text-sm leading-6 text-muted-foreground">
                {titles[step][1]}
              </p>
              <Auth06FormError id={formErrorId} message={submitting.error} />
              {step === "account" ? (
                <Auth06AccountForm
                  {...shared}
                  errors={{ ...errors, email: errors.email || checking.error }}
                  checking={checking.pending}
                  agreementLinks={agreementLinks}
                  onNext={() => void nextFromAccount()}
                />
              ) : step === "profile" ? (
                <Auth06ProfileForm
                  {...shared}
                  regions={regions}
                  teamSizes={teamSizes}
                  last={identityStep === "off"}
                  submitting={submitting.pending}
                  onBack={() => goTo("account")}
                  onNext={nextFromProfile}
                />
              ) : step === "identity" ? (
                <Auth06IdentityForm
                  {...shared}
                  mode={identityStep === "required" ? "required" : "optional"}
                  submitting={submitKind}
                  onBack={() => goTo("profile")}
                  onSubmit={(withIdentity) => void submitAll(withIdentity)}
                />
              ) : (
                <Auth06DonePanel
                  labels={labels}
                  identity={
                    identityStep === "off"
                      ? "off"
                      : submitted?.identity
                        ? "submitted"
                        : "pending"
                  }
                  onEnter={() => submitted && onSuccess?.(submitted)}
                />
              )}
            </motion.div>
          </div>
        </GridSection>
        {onSignIn && step !== "done" && (
          <>
            <GridSeparator />
            <GridSection className="px-4 py-4 text-center sm:px-6">
              <Button type="button" variant="link" size="lg" onClick={onSignIn}>
                {labels.signIn}
              </Button>
            </GridSection>
          </>
        )}
      </GridContainer>
    </div>
  )
}

export { Auth06 }
export type {
  Auth06IdentityMode,
  Auth06Props,
  Auth06Region,
  Auth06Step,
  Auth06TeamSize,
  Auth06Values,
} from "./types"
export type { Auth06Labels } from "./config"

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }

"use client"
import * as React from "react"
import { Auth06 } from "@/components/auth-06/auth-06"

const wait = () => new Promise((resolve) => setTimeout(resolve, 350))

// 放在组件外保持引用稳定；import() 让地区数据单独成块，首次打开地区选择时才下载
const loadRegions = () =>
  import("@/lib/china-regions").then((m) => m.chinaRegions)

/** 演示后端仅用于体验界面，接入时替换为真实的注册服务。 */
export default function SignUpPage() {
  const [notice, setNotice] = React.useState("")
  return (
    <main
      data-slot="auth-06-demo"
      className="flex min-h-screen flex-col justify-center bg-background py-8 text-foreground"
    >
      <p className="mb-4 px-4 text-center text-xs text-muted-foreground">
        演示：邮箱 taken@example.com 视为已注册；手机号以 0000 结尾时提交失败
      </p>
      <Auth06
        brand={{ name: "云间工作台" }}
        regions={loadRegions}
        onCheckEmail={async (email) => {
          await wait()
          if (email.toLowerCase() === "taken@example.com")
            throw new Error("该邮箱已注册，可以直接登录")
        }}
        onSubmit={async (values) => {
          await wait()
          if (values.phone.endsWith("0000"))
            throw new Error("注册服务暂时不可用，请稍后重试")
        }}
        onSuccess={() => setNotice("请在接入后跳转到工作台")}
        onSignIn={() => setNotice("请在接入后打开登录页面")}
      />
      <p
        role="status"
        className="mt-4 px-4 text-center text-xs text-muted-foreground"
      >
        {notice}
      </p>
    </main>
  )
}

import type * as React from "react"
import type { RegionsSource } from "@/components/ui/region-picker/region-picker"
import type { Auth06Labels } from "./config"

/** 向导所处的位置；`done` 是提交成功后的结果页，不算一步。 */
type Auth06Step = "account" | "profile" | "identity" | "done"

/** 实名步骤：可跳过、必填或不出现（整个向导只有两步）。 */
type Auth06IdentityMode = "optional" | "required" | "off"

type Auth06Region = {
  /** 最末一级的行政区划代码 */
  code: string
  /** 从省到市的名称，如 `["浙江省", "杭州市"]` */
  path: string[]
}

type Auth06Values = {
  email: string
  password: string
  name: string
  /** 11 位纯数字，不带区号 */
  phone: string
  region: Auth06Region
  /** 所选团队规模选项的 `value` */
  teamSize: string
  /** 跳过实名时没有这一项 */
  identity?: { realName: string; idNumber: string }
}

type Auth06TeamSize = { value: string; label: string }

/** 向导内部的草稿：前后切换步骤时全部保留。 */
type Auth06Draft = {
  email: string
  password: string
  agreed: boolean
  name: string
  phone: string
  region: string | null
  regionPath: string[]
  teamSize: string
  realName: string
  idNumber: string
}

type Auth06Errors = Partial<Record<keyof Auth06Draft, string>>

type Auth06Props = Omit<React.ComponentProps<"div">, "onSubmit"> & {
  /** 地区数据，传数组或惰性加载函数，同 `RegionPicker` 的 `regions`。 */
  regions: RegionsSource
  /** 最后一步统一提交，失败时抛出 Error，`message` 显示在当前步骤表单上方。 */
  onSubmit: (values: Auth06Values) => Promise<void>
  /** 第一步「下一步」时检查邮箱是否可用；抛出的 `message` 显示在邮箱下方。 */
  onCheckEmail?: (email: string) => Promise<void>
  /** 结果页点「进入工作台」时触发，参数为已提交的值。 */
  onSuccess?: (values: Auth06Values) => void
  /** 传入后底部显示「已有账号？去登录」，导航由接入方处理。 */
  onSignIn?: () => void
  /** 实名步骤。@default "optional" */
  identityStep?: Auth06IdentityMode
  /** 团队规模选项，第一项为默认值。@default 仅自己 / 2–10 人 / 11–50 人 / 50 人以上 */
  teamSizes?: Auth06TeamSize[]
  /** 协议链接；未提供时只显示协议名称。 */
  agreementLinks?: { terms?: string; privacy?: string }
  /** 品牌名称和标志。 */
  brand?: { name: string; logo?: React.ReactNode }
  /** 覆盖默认中文文案。 */
  labels?: Partial<Auth06Labels>
  /** 受控步骤。 */
  step?: Auth06Step
  /** 初始步骤。@default "account" */
  defaultStep?: Auth06Step
  /** 步骤变化通知（前进、返回、点步骤栏、完成）。 */
  onStepChange?: (step: Auth06Step) => void
}

export type {
  Auth06Draft,
  Auth06Errors,
  Auth06IdentityMode,
  Auth06Props,
  Auth06Region,
  Auth06Step,
  Auth06TeamSize,
  Auth06Values,
}

import { z } from "zod"
import { isValidIdCard } from "@/components/ui/id-number-input/id-number-input"
import { isValidPhone } from "@/components/ui/phone-input/phone-input"
import type { Auth06Labels } from "./config"

function createAccountSchema(labels: Auth06Labels) {
  return z.object({
    email: z.string().trim().email(labels.emailError),
    password: z.string().min(8, labels.passwordError),
    agreed: z.boolean().refine(Boolean, labels.agreementError),
  })
}

function createProfileSchema(labels: Auth06Labels) {
  return z.object({
    name: z.string().trim().min(1, labels.nameError),
    phone: z.string().refine(isValidPhone, labels.phoneError),
    region: z.string().min(1, labels.regionError),
  })
}

function createIdentitySchema(labels: Auth06Labels) {
  return z.object({
    realName: z.string().trim().min(2, labels.realNameError),
    idNumber: z
      .string()
      .refine((value) => isValidIdCard(value), labels.idNumberError),
  })
}

/** 把 zod 的错误按字段名收成「字段 → 第一条信息」。 */
function fieldErrors(error: z.ZodError) {
  const result: Record<string, string> = {}
  for (const issue of error.issues) {
    const key = String(issue.path[0] ?? "")
    if (!result[key]) result[key] = issue.message
  }
  return result
}

export {
  createAccountSchema,
  createIdentitySchema,
  createProfileSchema,
  fieldErrors,
}

"use client"
import * as React from "react"
/** 用同步锁拦截自动提交与回车的重复请求。 */
function useAsyncAction(fallback: string) {
  const lock = React.useRef(false)
  const [pending, setPending] = React.useState(false)
  const [error, setError] = React.useState("")
  async function run(action: () => Promise<void>) {
    if (lock.current) return false
    lock.current = true
    setPending(true)
    setError("")
    try {
      await action()
      return true
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : fallback)
      return false
    } finally {
      lock.current = false
      setPending(false)
    }
  }
  return { pending, error, setError, run }
}
export { useAsyncAction }

"use client"

import * as React from "react"
import { ChevronLeft, Eye, EyeOff } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { cn } from "@/lib/utils"
import { BarField, type BarFieldProps } from "@/components/ui/bar-field/bar-field"
import type { Auth06Labels } from "./config"

/** 带显示 / 隐藏切换的密码方条；切换键与条同高，放在条内右侧。 */
function Auth06PasswordField({
  labels,
  ...props
}: Omit<BarFieldProps, "type" | "suffix"> & { labels: Auth06Labels }) {
  const [visible, setVisible] = React.useState(false)
  return (
    <BarField
      {...props}
      type={visible ? "text" : "password"}
      suffix={
        <Button
          type="button"
          variant="ghost"
          size="icon-lg"
          aria-label={visible ? labels.hidePassword : labels.showPassword}
          aria-pressed={visible}
          onClick={() => setVisible((value) => !value)}
          className="text-muted-foreground hover:text-foreground"
        >
          {visible ? <EyeOff aria-hidden="true" /> : <Eye aria-hidden="true" />}
        </Button>
      }
    />
  )
}

/** 协议勾选：错误文字用 role="alert" 播报，并通过 aria-describedby 关联到复选框。 */
function Auth06Agreement({
  id,
  labels,
  checked,
  error,
  disabled,
  links,
  onCheckedChange,
}: {
  id: string
  labels: Auth06Labels
  checked: boolean
  error?: string
  disabled?: boolean
  links?: { terms?: string; privacy?: string }
  onCheckedChange: (checked: boolean) => void
}) {
  const errorId = `${id}-error`
  const link = (href: string | undefined, text: string) =>
    href ? (
      <a href={href} className="text-foreground underline underline-offset-4">
        {text}
      </a>
    ) : (
      text
    )
  return (
    <div data-slot="auth-06-agreement" className="space-y-1.5">
      <div className="flex items-start gap-3 text-xs leading-6 text-muted-foreground">
        <Checkbox
          id={id}
          checked={checked}
          disabled={disabled}
          onCheckedChange={(value) => onCheckedChange(value)}
          aria-invalid={error ? true : undefined}
          aria-describedby={error ? errorId : undefined}
          className="mt-1"
        />
        <p>
          <label htmlFor={id}>{labels.agreement}</label>
          {link(links?.terms, labels.terms)}
          {labels.and}
          {link(links?.privacy, labels.privacy)}
        </p>
      </div>
      {error && (
        <p role="alert" id={errorId} className="text-xs text-destructive">
          {error}
        </p>
      )}
    </div>
  )
}

/** 表单级错误（提交失败的原因），出现时读屏立即朗读。 */
function Auth06FormError({ id, message }: { id: string; message: string }) {
  if (!message) return null
  return (
    <p
      id={id}
      role="alert"
      data-slot="auth-06-form-error"
      className="mb-5 rounded-md border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm text-destructive"
    >
      {message}
    </p>
  )
}

/** 每步底部的按钮行：左「上一步」，右侧次要操作 + 主按钮，同一档高度。 */
function Auth06Actions({
  labels,
  onBack,
  disabled,
  children,
}: {
  labels: Auth06Labels
  onBack?: () => void
  disabled?: boolean
  children: React.ReactNode
}) {
  return (
    <div
      data-slot="auth-06-actions"
      className="mt-8 flex items-center gap-2 border-t border-dashed border-edge pt-5"
    >
      {onBack && (
        <Button
          type="button"
          variant="ghost"
          size="lg"
          disabled={disabled}
          onClick={onBack}
          className="-ml-2.5 text-muted-foreground"
        >
          <ChevronLeft aria-hidden="true" />
          {labels.back}
        </Button>
      )}
      <div className="ml-auto flex items-center gap-2">{children}</div>
    </div>
  )
}

/** 按钮文字在几种状态间切换时叠放全部候选，按钮宽度取最长的一个，不跳动。 */
function Auth06ButtonLabel({
  current,
  options,
}: {
  current: string
  options: string[]
}) {
  return (
    <span data-slot="auth-06-button-label" className="grid">
      {options.map((option) => (
        <span
          key={option}
          className={cn(
            "col-start-1 row-start-1",
            option !== current && "invisible",
          )}
        >
          {option}
        </span>
      ))}
    </span>
  )
}

